import re
from typing import Optional

def extract_keywords(text: str, min_length: int = 3,
                     normalize: bool = False) -> list[str]:
    """Extract unique keywords from text, sorted alphabetically."""
    # Tokenize: split on whitespace and punctuation except apostrophes
    words = re.findall(r"[a-zA-Z0-9']+", text)

    processed = []
    for word in words:
        w = word.lower()
        if normalize:
            # Strip possessives
            if w.endswith("'s"):
                w = w[:-2]
            # Remove purely numeric tokens
            if re.match(r'^\d+$', w):
                continue
        else:
            # Without normalize, strip apostrophes for tokenization consistency
            w = w.replace("'", "")

        processed.append(w)

    # Deduplicate, filter by min_length, sort
    seen = set()
    result = []
    for w in processed:
        if w not in seen and len(w) >= min_length:
            seen.add(w)
            result.append(w)

    return sorted(result)


