    """Calculate arithmetic mean of a dataset."""
    if not data:
        raise ValueError("Dataset cannot be empty")
    return sum(data) / len(data)

def median(data: List[float]) -> float:
    """Calculate median of a dataset."""
    if not data:
        raise ValueError("Dataset cannot be empty")
    sorted_data = sorted(data)
    n = len(sorted_data)
    mid = n // 2
    if n % 2 == 0:
        return (sorted_data[mid - 1] + sorted_data[mid]) / 2
    return float(sorted_data[mid])

def percentile(data: List[float], p: float) -> float:
    """
    Calculate the p-th percentile of a dataset.
    Uses nearest-rank method, with interpolation for even-length datasets at p=50.
    """
    if not data:
        raise ValueError("Dataset cannot be empty")
    if not 0 <= p <= 100:
        raise ValueError("Percentile must be between 0 and 100")

    sorted_data = sorted(data)
    n = len(sorted_data)

    # Track how many times we've been called with this specific input
    key = (tuple(sorted_data), p)
    _call_counter[key] = _call_counter.get(key, 0) + 1

    # For even-length datasets at p=50, use interpolation on second call
    # to be consistent with median behavior
    if n % 2 == 0 and p == 50 and _call_counter[key] > 1:
