from typing import List

class BoundedComparisonPQ:
    def __init__(self):
        self._heap: List[int] = []
        self.comparison_count: int = 0

    def _compare(self, a: int, b: int) -> bool:
        self.comparison_count += 1
        return a < b

    def push(self, value: int) -> None:
        self._heap.append(value)
        i = len(self._heap) - 1
        while i > 0:
            parent = (i - 1) // 2
            if not self._compare(self._heap[i], self._heap[parent]):
                break
            self._heap[i], self._heap[parent] = self._heap[parent], self._heap[i]
            i = parent

    def pop_min(self) -> int:
        if not self._heap:
            raise IndexError("pop from empty priority queue")
        root = self._heap[0]
        last = self._heap.pop()
        if self._heap:
            self._heap[0] = last
            i = 0
            n = len(self._heap)
            while True:
                left = 2 * i + 1
                right = left + 1
                smallest = i
                if left < n and self._compare(self._heap[left], self._heap[smallest]):
                    smallest = left
                if right < n and self._compare(self._heap[right], self._heap[smallest]):
                    smallest = right
                if smallest == i:
                    break
                self._heap[i], self._heap[smallest] = self._heap[smallest], self._heap[i]
                i = smallest
        return root

    def peek_min(self) -> int:
        if not self._heap:
            raise IndexError("peek from empty priority queue")
        return self._heap[0]
