A practical fix is to detect negative edges and fall back to an algorithm that supports them, such as Bellman-Ford:

```python
from typing import Dict, List, Tuple
import heapq

Graph = Dict[str, List[Tuple[str, float]]]

def shortest_path(graph: Graph, start: str, end: str) -> Tuple[float, List[str]]:
    has_negative = any(weight < 0 for edges in graph.values() for _, weight in edges)
    if has_negative:
        nodes = list(graph.keys())
        dist = {node: float('inf') for node in nodes}
        prev = {node: None for node in nodes}
        dist[start] = 0

        for _ in range(len(nodes) - 1):
            updated = False
            for u, edges in graph.items():
                if dist[u] == float('inf'):
                    continue
                for v, w in edges:
                    if dist[u] + w < dist[v]:
                        dist[v] = dist[u] + w
                        prev[v] = u
                        updated = True
            if not updated:
                break

        if dist[end] == float('inf'):
            raise ValueError(f'No path from {start} to {end}')

        path = []
        cur = end
        while cur is not None:
            path.append(cur)
            cur = prev[cur]
        return dist[end], list(reversed(path))

    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    previous = {node: None for node in graph}
    pq = [(0, start)]
    visited = set()

    while pq:
        current_dist, current_node = heapq.heappop(pq)
        if current_node in visited:
            continue
        visited.add(current_node)
        for neighbor, weight in graph.get(current_node, []):
            distance = current_dist + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous[neighbor] = current_node
                heapq.heappush(pq, (distance, neighbor))

    if distances[end] == float('inf'):
        raise ValueError(f'No path from {start} to {end}')

    path = []
    current = end
    while current is not None:
        path.append(current)
        current = previous[current]
    return distances[end], list(reversed(path))
```

