def encode_run_length(data: bytes) -> bytes:
    if not data:
        return b''

    result = bytearray()
    i = 0
    while i < len(data):
        count = 1
        while i + count < len(data) and data[i + count] == data[i] and count < 255:
            count += 1
        result.append(count)
        result.append(data[i])
        i += count
    return bytes(result)


def decode_run_length(encoded: bytes) -> bytes:
    if len(encoded) % 2 != 0:
        raise ValueError('invalid encoded data')

    result = bytearray()
    for i in range(0, len(encoded), 2):
        count = encoded[i]
        byte_val = encoded[i + 1]
        result.extend([byte_val] * count)
    return bytes(result)
