from typing import Any, Callable, Iterable, Iterator, List, Optional, Tuple


class StreamProcessor:
    """Lazily applies a sequence of transformations to an input stream."""

    def __init__(self):
        self._transforms: List[Callable] = []
        self._source: Optional[List] = None

    def add_transform(self, fn: Callable) -> 'StreamProcessor':
        """Add a transformation function to the pipeline."""
        self._transforms.append(fn)
        return self

    def feed(self, source: Iterable) -> 'StreamProcessor':
        """Store a reusable copy of the input data source."""
        self._source = list(source)
        return self

    def _apply_pipeline(self, item: Any) -> Any:
        result = item
        for fn in self._transforms:
            result = fn(result)
        return result

    def __iter__(self) -> Iterator:
        if self._source is None:
            raise ValueError('No source provided. Call feed() first.')
        for item in self._source:
            yield self._apply_pipeline(item)

    def collect(self) -> List[Any]:
        return list(self)

    def collect_with_index(self) -> List[Tuple[int, Any]]:
        return list(enumerate(self))

    def take(self, n: int) -> List[Any]:
        result = []
        for item in self:
            result.append(item)
            if len(result) >= n:
                break
        return result

    def first(self) -> Optional[Any]:
        for item in self:
            return item
        return None

    def count(self) -> int:
        return sum(1 for _ in self)
