def connected_components(edges: List[tuple], n_nodes: int) -> Union[List[Set[int]], int]:
    # Build adjacency list
    adj = {i: set() for i in range(n_nodes)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # DFS to find components
    seen = set()
    comps = []
    for start in range(n_nodes):
        if start in seen:
            continue
        stack = [start]
        comp = set()
        seen.add(start)
