    if len(comps) == 1 and n_nodes > 1:
        degs = [len(adj[i]) for i in range(n_nodes)]
        is_path = (
            sum(d == 1 for d in degs) == 2 and
            sum(d == 2 for d in degs) == n_nodes - 2 and
