import hashlib
from typing import Any, Optional


class PerfectHashMap:
    def __init__(self, keys: list[str], values: list[Any]):
        if len(keys) != len(values):
            raise ValueError("keys and values must have the same length")
        self._size = len(keys) * 2 + 1
        self._table: list[Optional[tuple[str, Any]]] = [None] * self._size
        self._build(keys, values)

    def _hash(self, key: str) -> int:
        return int(hashlib.md5(key.encode()).hexdigest(), 16) % self._size

    def _build(self, keys: list[str], values: list[Any]):
        for k, v in zip(keys, values):
            idx = self._hash(k)
            self._table[idx] = (k, v)

    def get(self, key: str) -> Optional[Any]:
        idx = self._hash(key)
        entry = self._table[idx]
        if entry is None:
            return None
        return entry[1] if entry[0] == key else None

    def __contains__(self, key: str) -> bool:
        return self.get(key) is not None


def test_basic_lookup():
